  'Medical Anthropology',
  'Medical Anthropology',
  'Medical Anthropology examines health, illness, healing, suffering, and care as biological, cultural, political, economic, ecological, and moral phenomena. Students learn to analyze clinical systems, public health programs, epidemics, mental health, reproduction, disability, technology, and global health through ethnographic and biocultural methods.',
  $medajson${"slug": "medical-anthropology", "title": "Medical Anthropology", "description": "Medical Anthropology examines health, illness, healing, suffering, and care as biological, cultural, political, economic, ecological, and moral phenomena. Students learn to analyze clinical systems, public health programs, epidemics, mental health, reproduction, disability, technology, and global health through ethnographic and biocultural methods.", "topics": [{"id": "d0b00073-c8e7-40a8-8c34-d87254be7f3b", "type": "topic", "title": "Culture, Embodiment, Illness Experience, and Explanatory Models", "description": "Students begin with illness as lived experience, learning how symptoms, suffering, diagnosis, and healing are shaped by culture, biography, body, language, and social relation.", "children": [{"id": "2d9170ed-bbcf-4a7a-a0b8-74cf75776689", "type": "subtopic", "title": "Illness, disease, and sickness", "children": [{"id": "c3a9dc05-a05d-46de-a524-cc3519ea2cec", "type": "concept", "title": "Illness narratives"}, {"id": "57f70ad8-b0d5-44df-89d5-7e38634a773b", "type": "concept", "title": "Disease categories"}, {"id": "5be416a7-9d50-41bf-92ab-130d87e042a2", "type": "concept", "title": "Sickness roles"}, {"id": "4dc63788-4b74-4bcc-a894-d1b874d67365", "type": "concept", "title": "Clinical and lay vocabularies"}], "description": "This distinction helps students separate biological pathology from subjective experience and social recognition."}, {"id": "6fc598dc-7358-4d9b-ad4d-1e18cd45186f", "type": "subtopic", "title": "Embodiment and the body", "children": [{"id": "7eb01659-a741-422d-910b-f673db4ae91c", "type": "concept", "title": "Lived body"}, {"id": "e8841c56-42ae-461a-bf3b-357716c9c85f", "type": "concept", "title": "Somatization and distress"}, {"id": "30db9e9c-e108-4bd7-96cf-d5c1fe4487c6", "type": "concept", "title": "Pain and perception"}, {"id": "ca32ddb7-b313-4051-b082-dbcc5da022c0", "type": "concept", "title": "Habit, discipline, and bodily technique"}], "description": "Embodiment frames the body as biological, social, political, historical, and sensorial at once."}, {"id": "5c03db67-f534-4e97-8d22-125647b51c49", "type": "subtopic", "title": "Explanatory models", "children": [{"id": "01b1c219-2261-4ea7-9f8d-d66c36e1934f", "type": "concept", "title": "Etiology"}, {"id": "c067575c-4a38-4bd5-acfa-a10fd537b8a9", "type": "concept", "title": "Help-seeking pathways"}, {"id": "9413ceef-413b-41ac-b3d3-8fd18c9548b1", "type": "concept", "title": "Treatment expectations"}, {"id": "b656e969-b6db-4c52-9e17-15ccde2ad40c", "type": "concept", "title": "Miscommunication and negotiation"}], "description": "Students learn to ask how patients, families, clinicians, and institutions explain causes, risks, treatments, and outcomes."}]}, {"id": "2b5bdf04-4656-4f72-9a2c-f6e612346195", "type": "topic", "title": "Biomedicine as a Cultural System and Clinical World", "description": "This section treats biomedicine not as culture-free science but as a powerful institution with values, rituals, hierarchies, technologies, and forms of knowledge.", "children": [{"id": "91386f6a-4e24-4d2c-b813-999d1788f16b", "type": "subtopic", "title": "Medicalization and diagnosis", "children": [{"id": "52ac76ca-aca0-49a0-96ad-39838a23e4fd", "type": "concept", "title": "Expansion of disease categories"}, {"id": "e32038e3-fdb1-4804-b558-a53012bf9bcb", "type": "concept", "title": "Screening and risk"}, {"id": "a046a6c3-edc9-4264-a664-d6baac693557", "type": "concept", "title": "Labeling effects"}, {"id": "ed941d0c-a941-483f-9009-700080244adb", "type": "concept", "title": "Contested illness"}], "description": "Students examine how human problems become medical categories and why diagnostic labels can both help and constrain."}, {"id": "e856a55e-23b0-4b39-b043-62af4fb9fa37", "type": "subtopic", "title": "Clinical training and professional identity", "children": [{"id": "98ece14a-9bf1-4d4b-8550-7dd1c09c7654", "type": "concept", "title": "Hidden curriculum"}, {"id": "7c84b98b-ca8b-47e6-ba3d-0dfc55109714", "type": "concept", "title": "Case presentation"}, {"id": "fdf9cd6d-2c5a-43be-84db-360f2e9caeff", "type": "concept", "title": "Objectivity and detachment"}, {"id": "61dc4e3f-907c-48c6-a792-a3063ea6bdb8", "type": "concept", "title": "Bedside authority"}], "description": "This subtopic reveals how clinicians learn to see, speak, document, and decide within institutional norms."}, {"id": "79b24257-dbf4-4147-ae55-e9ebe8fb66bd", "type": "subtopic", "title": "Patient-provider encounters", "children": [{"id": "13643a95-5236-404d-b8db-f97b14943f19", "type": "concept", "title": "Narrative medicine"}, {"id": "1cff64c4-eef4-4e10-bb53-3b38138f7bdb", "type": "concept", "title": "Shared decision-making"}, {"id": "353cb46c-f43d-4a47-8224-0497293c4bd3", "type": "concept", "title": "Language access"}, {"id": "1c29dbf0-94f3-4338-8038-246cb0121b93", "type": "concept", "title": "Moral distress"}], "description": "Students connect cultural competence to deeper questions of power, listening, translation, time pressure, and trust."}]}, {"id": "f00020b0-6647-4a6a-9831-274290f045aa", "type": "topic", "title": "Healing Systems, Therapeutic Pluralism, Religion, and Ritual", "description": "Students compare multiple forms of healing without reducing them to superstition or preference, asking what therapeutic systems do socially, symbolically, and bodily.", "children": [{"id": "8537f795-b0b9-4fc3-8016-c31eda6502de", "type": "subtopic", "title": "Plural medical systems", "children": [{"id": "4d68aeb7-a477-4359-a193-b32a276ee6e9", "type": "concept", "title": "Medical syncretism"}, {"id": "a34ac6d0-aa07-4e95-9bd3-eda83b9c022e", "type": "concept", "title": "Local healing specialists"}, {"id": "fc65d110-5c55-40e9-8e62-16e0161cd327", "type": "concept", "title": "Herbal and household medicine"}, {"id": "d456c577-efbc-4cc4-8785-bc9ac766c48f", "type": "concept", "title": "Care itineraries"}], "description": "The goal is to understand why people often combine biomedical, religious, herbal, community, and household care."}, {"id": "9f0b4760-b019-4fad-bac6-96d8ebede230", "type": "subtopic", "title": "Ritual, symbolism, and efficacy", "children": [{"id": "58764179-e8f3-449d-ae80-a94991a78655", "type": "concept", "title": "Symbolic healing"}, {"id": "b40dc00e-a90e-40f7-967b-c68a104f6555", "type": "concept", "title": "Placebo and meaning response"}, {"id": "630950d3-fcc2-4e08-bba4-051e50df2e97", "type": "concept", "title": "Ritual authority"}, {"id": "ab320f0a-d755-4adb-bd53-e3173b32e4d9", "type": "concept", "title": "Community reintegration"}], "description": "Students learn how healing can work through meaning, social repair, expectation, performance, and embodied experience."}, {"id": "74b54f9d-e970-4727-84e4-3b02ea2a96cd", "type": "subtopic", "title": "Religion, spirituality, and care", "children": [{"id": "318da32c-d283-4148-b829-7c00e183acfa", "type": "concept", "title": "Prayer and pilgrimage"}, {"id": "db8fb4f2-5e50-4a9f-aed6-1cfb30d1b758", "type": "concept", "title": "Possession and affliction"}, {"id": "51010e06-3eda-4c40-abb6-45993fc5dfa7", "type": "concept", "title": "Pastoral care"}, {"id": "8fbdb9d5-1e78-4c76-a1dd-d858bd489577", "type": "concept", "title": "Death rituals"}], "description": "This subtopic equips students to analyze spiritual care as a serious dimension of illness, death, resilience, and moral world-making."}]}, {"id": "c8486310-89b3-42f6-ad39-c8998470fd81", "type": "topic", "title": "Biocultural Anthropology, Evolution, Nutrition, and Human Adaptation", "description": "Medical anthropology becomes strongest when students can connect biology and culture without collapsing one into the other.", "children": [{"id": "e4dbec2d-389b-42eb-b31d-0c4c45a98c0a", "type": "subtopic", "title": "Biocultural models", "children": [{"id": "701b492f-4199-4abc-9e02-e222d4259a2c", "type": "concept", "title": "Syndemics"}, {"id": "55edea18-4fef-48b3-849a-62a708fea99d", "type": "concept", "title": "Developmental origins"}, {"id": "19785459-0dba-465e-817a-ab36a169e150", "type": "concept", "title": "Stress physiology"}, {"id": "9679a799-2c54-401d-a19d-797b93ab4c77", "type": "concept", "title": "Ecological context"}], "description": "Students study how political economy, environment, stress, nutrition, and development become embodied as health patterns."}, {"id": "038fa620-dc26-4198-a11c-ada4fc73afe3", "type": "subtopic", "title": "Nutrition and food systems", "children": [{"id": "1afe3c2a-dd68-410b-be64-3d51adb7aa00", "type": "concept", "title": "Food insecurity"}, {"id": "25621146-0c75-4240-8b32-83b2a22b62f6", "type": "concept", "title": "Diet transitions"}, {"id": "51539421-1ec6-45a0-bd33-f5ebba573b9d", "type": "concept", "title": "Obesity and stigma"}, {"id": "e5eb4c3f-1826-47b4-b380-5798f4ecb060", "type": "concept", "title": "Agriculture and health"}], "description": "Food is treated as metabolism, identity, economy, labor, environment, and power."}, {"id": "5b51923f-48ad-44ce-a015-ec9dbefe3b30", "type": "subtopic", "title": "Evolutionary and comparative health", "children": [{"id": "0ff9d545-0da3-47a0-be17-6b3947708297", "type": "concept", "title": "Life history"}, {"id": "17282552-286a-4bd6-850f-df545c128f84", "type": "concept", "title": "Mismatch theory"}, {"id": "b3c1257a-caa5-429f-befc-118b3a36faf0", "type": "concept", "title": "Immune adaptation"}, {"id": "fd79f290-50d0-47c9-a1a7-190d4a6342a3", "type": "concept", "title": "Reproductive ecology"}], "description": "This subtopic introduces careful evolutionary reasoning about bodies, environments, and modern disease burdens."}]}, {"id": "b733ff48-ec26-4c71-8a20-ef1832604aa8", "type": "topic", "title": "Structural Violence, Social Determinants, Inequality, and Health Justice", "description": "Students learn to move beyond individual behavior explanations and analyze how institutions, histories, policies, and economies produce patterned suffering.", "children": [{"id": "32e11354-95e2-4457-88e6-cf4be62e05a3", "type": "subtopic", "title": "Structural violence", "children": [{"id": "2db367b6-7277-4de8-8784-0ef77b49cd6b", "type": "concept", "title": "Poverty and vulnerability"}, {"id": "1cc3ecf8-81f9-4df0-a9a8-b83aadd6f626", "type": "concept", "title": "Institutional neglect"}, {"id": "3500e7c3-291c-41b1-9396-7592f4b54c86", "type": "concept", "title": "Slow violence"}, {"id": "26acca1e-4bd8-4e56-b521-414b29d2f86c", "type": "concept", "title": "Moral economy of care"}], "description": "The point is to see how harm can be built into ordinary arrangements of labor, housing, law, borders, and care."}, {"id": "03a85e9e-2e10-4448-b13c-a23cc1b5401c", "type": "subtopic", "title": "Social determinants of health", "children": [{"id": "c27c2db9-bca5-4f33-9126-b622ce81a0a8", "type": "concept", "title": "Neighborhood effects"}, {"id": "1a79e89d-7655-4741-b72a-d81a97f52b2d", "type": "concept", "title": "Employment and precarity"}, {"id": "bfaf9320-ed89-4e97-a2c1-6f9a5d1b2342", "type": "concept", "title": "Food and transport"}, {"id": "a4b05266-6836-4cc8-94aa-343aeb87126b", "type": "concept", "title": "Health system access"}], "description": "Students connect anthropological theory to public health frameworks for housing, education, work, discrimination, and access."}, {"id": "e14bc717-8637-4909-8cbb-875672e41dc8", "type": "subtopic", "title": "Health equity and justice", "children": [{"id": "b0ac8f3c-1325-47c6-85c6-250595f93539", "type": "concept", "title": "Equity vs equality"}, {"id": "c581af21-3eee-4102-a997-3d28b08691d4", "type": "concept", "title": "Accountability"}, {"id": "0890e355-131a-4061-bda9-8f28c76b271a", "type": "concept", "title": "Community power"}, {"id": "0574e02e-ce01-49fc-ae1f-55416bd71148", "type": "concept", "title": "Redistribution and recognition"}], "description": "This subtopic focuses on analysis that can support fairer systems without flattening lived experience into metrics alone."}]}, {"id": "32a0362b-0603-42a0-8a36-45b3ac4ee30a", "type": "topic", "title": "Race, Racism, Colonialism, Indigeneity, and Decolonizing Health", "description": "Students examine how racial categories, colonial governance, dispossession, and medical institutions have shaped health knowledge and health inequality.", "children": [{"id": "95b40cac-f1a0-4c81-8ea4-d1d44f9b9253", "type": "subtopic", "title": "Race and medicine", "children": [{"id": "046effb6-3d69-4106-9bf5-7e1e355c29a9", "type": "concept", "title": "Race correction debates"}, {"id": "353ceae3-5ce9-4b81-944a-3859dba0583b", "type": "concept", "title": "Genetics and ancestry"}, {"id": "23608dcc-6e50-4d61-b747-f6d0fcc67124", "type": "concept", "title": "Racism as exposure"}, {"id": "4bfcf077-892b-4a8e-8ca9-be30867307a1", "type": "concept", "title": "Diagnostic bias"}], "description": "Students distinguish biological variation from racialized social hierarchy and learn why race remains powerful in clinical systems."}, {"id": "c94f103c-363f-4da6-b0a1-a27533840a4b", "type": "subtopic", "title": "Colonial medicine and global hierarchies", "children": [{"id": "52f04985-9679-4552-a54c-a13cabf23bad", "type": "concept", "title": "Tropical medicine"}, {"id": "cdbd5a9c-c737-42bf-8339-0b81afcbba6d", "type": "concept", "title": "Mission medicine"}, {"id": "d72a0a25-0b1a-44ce-8de4-39f93a4358cc", "type": "concept", "title": "Eugenics"}, {"id": "151fa27f-03d2-4203-826a-8592e0dcd8c9", "type": "concept", "title": "Research exploitation"}], "description": "This subtopic traces how medicine has been used for control, extraction, experimentation, and legitimation."}, {"id": "a4acf835-0e97-447d-ad8e-6e4d298f7e6e", "type": "subtopic", "title": "Indigenous health and sovereignty", "children": [{"id": "eef4f12b-b30e-42bf-8fbf-486a9f66dd58", "type": "concept", "title": "Settler colonialism"}, {"id": "68fb4167-4977-400b-b753-a31467c57bff", "type": "concept", "title": "Traditional knowledge"}, {"id": "a08862fa-00de-4dec-abf4-27d288d3feec", "type": "concept", "title": "Data sovereignty"}, {"id": "d1969cf0-3b7c-477b-9bf1-dc8edc05d3ef", "type": "concept", "title": "Community-led care"}], "description": "Students learn to center land, governance, cultural continuity, and self-determination in Indigenous health."}]}, {"id": "f71f79f7-0947-456a-9f99-f7663a56ad21", "type": "topic", "title": "Global Health Institutions, Development, Humanitarianism, and Aid", "description": "Global health is studied as a field of intervention, funding, expertise, measurement, and moral imagination rather than a neutral delivery apparatus.", "children": [{"id": "3a321ad4-f18b-458d-8551-f0561e9bf543", "type": "subtopic", "title": "Global health governance", "children": [{"id": "49633c69-8d22-4a69-b531-cbf6ff0643cc", "type": "concept", "title": "WHO and multilateralism"}, {"id": "557fb619-a0ce-46d2-8bd5-66e95685a818", "type": "concept", "title": "Donor priorities"}, {"id": "847ffd1a-0991-4404-b552-a34323d07bf3", "type": "concept", "title": "Vertical vs horizontal programs"}, {"id": "ce24b9e4-a6e8-4b32-96ac-833977d764ae", "type": "concept", "title": "Accountability chains"}], "description": "Students map how agencies, donors, NGOs, states, and experts define priorities and distribute authority."}, {"id": "dc527c6f-18d3-4030-8307-fda723312c42", "type": "subtopic", "title": "Development and humanitarianism", "children": [{"id": "29b2528c-ccef-4ee0-a847-0d3fa991b814", "type": "concept", "title": "Project cycles"}, {"id": "e1f1ca7c-eea0-46de-ac3a-c8d878d5b9cb", "type": "concept", "title": "Emergency response"}, {"id": "46dd4c87-bdf0-48f4-b2b2-4ef3725bf3b0", "type": "concept", "title": "NGOization"}, {"id": "3dc4bff2-4f0e-450b-8ce9-6c6fa4e52a2c", "type": "concept", "title": "Unintended consequences"}], "description": "This subtopic asks when aid helps, when it harms, and how local actors navigate intervention landscapes."}, {"id": "0c323a2c-1d81-482c-8b93-e363b6098a4b", "type": "subtopic", "title": "Metrics, evidence, and audit culture", "children": [{"id": "7bd6f85b-589e-4651-94c1-11738b203282", "type": "concept", "title": "Burden of disease"}, {"id": "d9f5f5f7-d62a-4dd6-ae11-ad4cf27c5d51", "type": "concept", "title": "Cost-effectiveness"}, {"id": "77934a52-cd32-4444-b0c5-d98ad3069844", "type": "concept", "title": "Randomized trials"}, {"id": "d92e1511-4c1c-465a-a0ea-dce2a3e26e91", "type": "concept", "title": "Ethnography of metrics"}], "description": "Students learn to critique how indicators make some needs visible while obscuring histories, relationships, and political causes."}]}, {"id": "26ac1366-ca0e-4650-9765-af1d1e5316aa", "type": "topic", "title": "Infectious Disease, Epidemics, Outbreak Response, and Syndemics", "description": "Students examine epidemics as biological, social, ecological, political, and communicative events.", "children": [{"id": "cded759f-29ad-4d2e-8973-224673f2d347", "type": "subtopic", "title": "Epidemics as social events", "children": [{"id": "abeabf17-510c-4ac3-b3d6-ecb4486eb1a6", "type": "concept", "title": "HIV/AIDS"}, {"id": "e2b19853-ac8f-4f79-8b1f-3fed5dd36993", "type": "concept", "title": "Ebola"}, {"id": "72bf6c36-5b3d-4b88-80e3-ed478edd11e4", "type": "concept", "title": "COVID-19"}, {"id": "28168fb2-980b-4ae9-9c2a-76bec3a95fa1", "type": "concept", "title": "Tuberculosis and malaria"}], "description": "This subtopic shows how fear, rumor, stigma, trust, labor, and governance shape disease transmission and response."}, {"id": "339e9bdc-c314-4936-a318-fc566686bee3", "type": "subtopic", "title": "Syndemics and co-morbidity", "children": [{"id": "d8c499f8-2ab2-4c19-a3d4-0407e941472d", "type": "concept", "title": "Substance use and HIV"}, {"id": "532a7c24-7168-4650-bd32-82007a78255d", "type": "concept", "title": "Diabetes and poverty"}, {"id": "30b01815-76ed-4068-a057-a58530d47722", "type": "concept", "title": "Mental health co-morbidity"}, {"id": "674ea392-16bf-44e9-a6c9-148f2281afca", "type": "concept", "title": "Climate-sensitive disease"}], "description": "Students learn how disease clusters interact with inequality, stress, environment, and policy."}, {"id": "f247c0ee-8269-4ea6-8bb4-f4dea45a8152", "type": "subtopic", "title": "Public health response and community trust", "children": [{"id": "e9411a39-3d71-4a4c-a2b9-1f281e16db91", "type": "concept", "title": "Contact tracing"}, {"id": "3cfc524f-d986-4f5b-b41a-178db4ae2dc5", "type": "concept", "title": "Vaccination campaigns"}, {"id": "ca1fcd4d-14e7-4e7a-96af-1f35ece11ca5", "type": "concept", "title": "Risk communication"}, {"id": "a601c3fa-91a1-4581-ad46-83d2ebae66d5", "type": "concept", "title": "Community health workers"}], "description": "This subtopic connects outbreak control to communication, local knowledge, historical memory, and legitimacy."}]}, {"id": "b588e428-4f59-46f7-9e24-851536ed87a1", "type": "topic", "title": "Mental Health, Psychiatry, Trauma, and Subjectivity", "description": "Students explore mental health across cultural worlds while avoiding both naive universalism and romantic relativism.", "children": [{"id": "eeccaff4-bf64-4f4a-82ba-e47bdc211aa8", "type": "subtopic", "title": "Culture and psychiatric categories", "children": [{"id": "3cbd6efe-7135-4d36-994b-fdbe30dc15d1", "type": "concept", "title": "DSM and ICD"}, {"id": "47787d2c-8b22-4f65-81b0-273fb8f9bfd8", "type": "concept", "title": "Culture-bound syndromes"}, {"id": "566fbf6c-c411-4feb-943e-8f6d8de39950", "type": "concept", "title": "Idioms of distress"}, {"id": "d26f947a-9fc0-4361-8aa4-9d09109f0941", "type": "concept", "title": "Diagnostic translation"}], "description": "The goal is to ask how diagnosis travels and how distress is named, treated, and contested."}, {"id": "9b3ff5cc-1ea5-4acb-be70-16ca4e10d783", "type": "subtopic", "title": "Trauma, memory, and violence", "children": [{"id": "b7fb1d1f-3f2d-4dbf-9bb9-e1afbf0243d7", "type": "concept", "title": "War and displacement"}, {"id": "63bdb24f-776d-468e-82ef-b6a04fc66de2", "type": "concept", "title": "Intergenerational trauma"}, {"id": "f5c73f90-0c87-4343-a06f-4c7e0b7d78cf", "type": "concept", "title": "Survivorship"}, {"id": "6cd8039f-9499-4732-ac79-820a28df4afc", "type": "concept", "title": "Human rights testimony"}], "description": "Students examine trauma as personal, collective, political, and historical."}, {"id": "5f35cc2f-abcb-403b-b3ff-3f2642711e81", "type": "subtopic", "title": "Psychiatric care and institutions", "children": [{"id": "d35c1285-7916-4c9f-94d2-64e59750281d", "type": "concept", "title": "Asylums and deinstitutionalization"}, {"id": "b3002346-3dc1-469d-a2fc-81354a1b3628", "type": "concept", "title": "Psychopharmaceuticals"}, {"id": "f4611c57-b6d5-4048-91c1-e0ae33cc2d52", "type": "concept", "title": "Community mental health"}, {"id": "f0a77449-1d69-41b1-b046-7082fa2ea43c", "type": "concept", "title": "Recovery movements"}], "description": "This subtopic studies therapies, pharmaceuticals, hospitals, community care, and coercion ethnographically."}]}, {"id": "71138288-6a68-471a-af1c-85045a72a7c8", "type": "topic", "title": "Reproduction, Gender, Sexuality, Bodies, and Life Course", "description": "This section treats reproduction and bodily life as key sites where intimate experience, state power, technology, ethics, and inequality meet.", "children": [{"id": "2d51fd09-1253-4fbb-b815-15289db52dcc", "type": "subtopic", "title": "Reproductive governance", "children": [{"id": "d4b052bd-a628-41a2-a46e-873e52e64ff6", "type": "concept", "title": "Contraception"}, {"id": "378145a2-c025-4896-ac13-b988a1bfd938", "type": "concept", "title": "Abortion politics"}, {"id": "482b2590-b23b-42b1-8f45-69a041a364e6", "type": "concept", "title": "Sterilization histories"}, {"id": "dbe5f71b-137a-4b30-a38e-82d07b87808f", "type": "concept", "title": "Population policy"}], "description": "Students analyze how states, clinics, markets, families, and religions shape reproductive choices and constraints."}, {"id": "69a8eec1-533e-4f35-b710-c91680600857", "type": "subtopic", "title": "Pregnancy, birth, and maternal health", "children": [{"id": "b4cf203c-8502-4333-b577-7bc83ab79d0d", "type": "concept", "title": "Medicalized birth"}, {"id": "2ae9bf32-7d9e-4e86-8d9a-ee8188207c00", "type": "concept", "title": "Midwifery and doulas"}, {"id": "6be6efb5-e4e0-4ee7-91f8-d2ec26f2f912", "type": "concept", "title": "Maternal mortality"}, {"id": "9d99c8ba-2265-4f76-bed4-b5b8f84a8243", "type": "concept", "title": "Risk surveillance"}], "description": "This subtopic connects embodied experience to obstetrics, midwifery, risk, race, and health systems."}, {"id": "dbde34d4-c4bf-409d-94e4-db3fd3738caa", "type": "subtopic", "title": "Gender, sexuality, and health", "children": [{"id": "11d00cc0-8603-4622-9136-e27f66f47a88", "type": "concept", "title": "LGBTQ+ health"}, {"id": "667bb96d-1b16-4d88-b850-65aa469d4b68", "type": "concept", "title": "Gender-based violence"}, {"id": "fb8e7257-ce18-43f2-a6fa-6be38590b304", "type": "concept", "title": "Sexual health"}, {"id": "469b6dd8-b96f-432d-b894-af12dc308585", "type": "concept", "title": "Body norms"}], "description": "Students study how gender and sexuality affect exposure, care, recognition, vulnerability, and resilience."}]}, {"id": "2f971eee-0a21-4656-93a6-8be2f8934707", "type": "topic", "title": "Disability, Chronic Illness, Aging, Care, and Death", "description": "Students learn to understand care as social labor, moral practice, institutional arrangement, and political question.", "children": [{"id": "f0869703-f9cb-4a5a-b2ba-c5eb41b5639c", "type": "subtopic", "title": "Chronicity and everyday life", "children": [{"id": "565851bc-b535-4e9f-b95d-621fdc8e491e", "type": "concept", "title": "Diabetes"}, {"id": "512acfdc-a98a-489d-b704-85e335dc564b", "type": "concept", "title": "Cancer survivorship"}, {"id": "b3bc2bc3-976b-4aba-a865-02e29a091e04", "type": "concept", "title": "Long COVID"}, {"id": "4476e3a7-d403-47e8-af6e-c44202486901", "type": "concept", "title": "Pain and fatigue"}], "description": "This subtopic focuses on how people live with long-term conditions across households, workplaces, clinics, and bureaucracies."}, {"id": "c25853a5-ca69-410d-a7e6-42926d485408", "type": "subtopic", "title": "Disability and accessibility", "children": [{"id": "48526906-2161-415b-88ba-635b3cf99330", "type": "concept", "title": "Social model of disability"}, {"id": "25d2dbc8-681f-4a5d-8d28-394cc5186d2f", "type": "concept", "title": "Assistive technologies"}, {"id": "137e0b51-ca4a-46f1-8e74-22e93a5a60fc", "type": "concept", "title": "Ableism"}, {"id": "541c6597-1dbb-4274-bfca-81976fddf8a9", "type": "concept", "title": "Independent living movements"}], "description": "Students examine disability as embodied variation, social exclusion, identity, activism, and design challenge."}, {"id": "843c16ee-d60a-4fcd-ac84-d2b4ea56f308", "type": "subtopic", "title": "Aging, caregiving, and death", "children": [{"id": "65758cc0-7572-44d3-bf5e-df0194d7b302", "type": "concept", "title": "Family caregiving"}, {"id": "46e739ca-7a2e-4b9b-9f95-ba7adb56105a", "type": "concept", "title": "Long-term care"}, {"id": "e4523080-54f8-47d2-a9e4-96f8100cad7a", "type": "concept", "title": "Palliative care"}, {"id": "ca682290-5f34-4932-8bcf-96ed2606300d", "type": "concept", "title": "End-of-life decision-making"}], "description": "The goal is to analyze later life and dying through kinship, institutions, economics, ethics, and ritual."}]}, {"id": "3bb9d8d4-cf24-4191-b587-60802e656143", "type": "topic", "title": "Pharmaceuticals, Biotechnology, Digital Health, and Science Studies", "description": "Medical technologies are studied as social objects that reshape diagnosis, identity, markets, expertise, and moral possibility.", "children": [{"id": "836e739d-618f-40ec-b073-6e1de8bf1b5a", "type": "subtopic", "title": "Pharmaceutical cultures", "children": [{"id": "1b4d8c49-5f51-4ab5-9960-93a0e9fb7cac", "type": "concept", "title": "Clinical trials"}, {"id": "49cccfb7-954a-478b-af5d-8172999d8422", "type": "concept", "title": "Direct-to-consumer advertising"}, {"id": "acf5d1b6-7817-4910-985a-6a9b3ae4bf2e", "type": "concept", "title": "Adherence"}, {"id": "62a052be-6f79-4da6-a1fc-08333387f419", "type": "concept", "title": "Off-label use"}], "description": "Students explore how drugs move through research, regulation, marketing, prescription, adherence, and everyday life."}, {"id": "a50ccca2-385b-4118-a685-d733c8fe9006", "type": "subtopic", "title": "Genomics, biotechnology, and risk", "children": [{"id": "93e40b85-6872-4ee3-b2fa-f91653d8eb0c", "type": "concept", "title": "Genetic testing"}, {"id": "9d15da23-05ab-4c4d-b9a0-ea70e0d237b2", "type": "concept", "title": "Biobanks"}, {"id": "995103de-102c-42cc-97ba-e3cafdace9bc", "type": "concept", "title": "Precision medicine"}, {"id": "23c96762-7158-4aeb-bb86-d4452d528f58", "type": "concept", "title": "Epigenetics"}], "description": "This subtopic asks how molecular knowledge changes kinship, identity, prediction, and responsibility."}, {"id": "56f95b44-4338-4706-b4ee-540637cb92bb", "type": "subtopic", "title": "Digital health and datafication", "children": [{"id": "fd91c3b1-94cf-49cb-8fde-f6bd943ef5bc", "type": "concept", "title": "AI triage"}, {"id": "930f5c10-7242-42af-8b42-65c9e37b642f", "type": "concept", "title": "Data privacy"}, {"id": "ded0adb6-33d5-466c-b97a-b1ba8adbbb73", "type": "concept", "title": "Quantified self"}, {"id": "8d38c3ce-8aca-416e-b2b6-3c78b7f9c37b", "type": "concept", "title": "Platform medicine"}], "description": "Students analyze apps, algorithms, telehealth, wearables, and electronic records as cultural and political systems."}]}, {"id": "4eb893bb-7467-4b5d-aa79-5d3710e70bcb", "type": "topic", "title": "Migration, Labor, Environment, Climate, and Planetary Health", "description": "Students connect health to movement, work, borders, ecological change, and planetary systems.", "children": [{"id": "23439ee3-730e-4c5e-bc12-6a100abad091", "type": "subtopic", "title": "Migration and border health", "children": [{"id": "35c22367-876f-4f91-9974-16c094fbebd1", "type": "concept", "title": "Migrant farmwork"}, {"id": "06ee3858-209b-4507-9fb9-991b2d48ac01", "type": "concept", "title": "Refugee care"}, {"id": "beb816ac-da98-4703-8eb1-64e5efc04065", "type": "concept", "title": "Medical deportation"}, {"id": "2f075c00-b4c9-443e-a829-e98a9003f95b", "type": "concept", "title": "Transnational treatment seeking"}], "description": "This subtopic examines health across mobility, documentation status, asylum, detention, and transnational family life."}, {"id": "7d922bec-b5b2-4f1b-9d25-57a4a5650e43", "type": "subtopic", "title": "Labor, occupational health, and care work", "children": [{"id": "f04ef343-9dc6-441b-9c82-58cc05af45ba", "type": "concept", "title": "Precarious labor"}, {"id": "0b1b0d2a-bff3-482f-b741-6d976d713b39", "type": "concept", "title": "Essential work"}, {"id": "1bab7a2e-97d5-4f70-acb8-b3020f95a959", "type": "concept", "title": "Occupational injury"}, {"id": "99cbc318-a27f-45c1-b0b6-93b8e0c42974", "type": "concept", "title": "Care worker inequality"}], "description": "Students study how bodies absorb the costs of food systems, service work, extraction, and care economies."}, {"id": "d2325004-ef22-4e53-a795-fcc8cc4ec188", "type": "subtopic", "title": "Climate and planetary health", "children": [{"id": "e0a54075-e17e-466b-aad5-aa73f5e39b72", "type": "concept", "title": "Heat and housing"}, {"id": "9277072e-2d84-4414-bd78-d227aaabee24", "type": "concept", "title": "Air pollution"}, {"id": "65d71922-3179-4539-bbd4-028b982ec118", "type": "concept", "title": "Environmental racism"}, {"id": "472ac476-83fc-4dee-8622-a36756cf40e5", "type": "concept", "title": "Eco-anxiety"}], "description": "The goal is to link ecological disruption to health without losing sight of unequal responsibility and vulnerability."}]}, {"id": "54d5864e-4cd2-445e-a283-6db90d229acc", "type": "topic", "title": "Ethnographic Methods, Ethics, Translation, and Mixed Evidence", "description": "This section gives students the research craft needed to study medicine and health responsibly.", "children": [{"id": "913a05dd-fbce-49d8-8288-c09035dcf636", "type": "subtopic", "title": "Participant observation in health settings", "children": [{"id": "8b93ae23-d0e0-4f1b-b0a7-24bc26bc16bc", "type": "concept", "title": "Fieldsite access"}, {"id": "b65e7634-1b9a-4e6a-a449-49ecbad180df", "type": "concept", "title": "Observation protocols"}, {"id": "939159cb-718a-4229-8629-7c9b48efa309", "type": "concept", "title": "Fieldnotes"}, {"id": "03617351-3b3b-4243-91a3-1ab973623e3f", "type": "concept", "title": "Researcher positionality"}], "description": "Students learn how to observe clinics, communities, households, and institutions while respecting vulnerability and confidentiality."}, {"id": "e13bae2f-6fb1-4203-9ff7-5656260aecaf", "type": "subtopic", "title": "Interviews, narratives, and qualitative analysis", "children": [{"id": "99e7a97c-bfa1-4277-b0b2-1fc4aee39150", "type": "concept", "title": "Semi-structured interviews"}, {"id": "b6b92f37-fea6-4266-a8e7-39e7fc2a6af7", "type": "concept", "title": "Oral histories"}, {"id": "aff2196a-84dd-45eb-9133-d8254582ce1e", "type": "concept", "title": "Coding"}, {"id": "4a395ba5-835f-46d5-b58a-308b04512b29", "type": "concept", "title": "Thematic analysis"}], "description": "This subtopic introduces rigorous qualitative design for illness stories, stakeholder perspectives, and program contexts."}, {"id": "46eef933-a52a-4051-b625-84c8d8bcfa6a", "type": "subtopic", "title": "Ethics, consent, and collaboration", "children": [{"id": "07667793-a2de-48c8-81a5-67f42cd9313a", "type": "concept", "title": "IRB"}, {"id": "29963148-ee91-4817-bbdb-b4c420a857fc", "type": "concept", "title": "Informed consent"}, {"id": "648b8b76-843a-4b1b-b4b1-1b131461a0fe", "type": "concept", "title": "Participatory methods"}, {"id": "2347f06c-7fbf-4912-a1dd-2df852a29517", "type": "concept", "title": "Data stewardship"}], "description": "Students practice research ethics beyond paperwork, emphasizing power, reciprocity, consent, and community benefit."}]}, {"id": "b989d0b4-57b8-4b85-81e2-49f8a07b3b83", "type": "topic", "title": "Applied Medical Anthropology, Policy, Intervention, and Capstone Synthesis", "description": "The course culminates in applying anthropological insight to real health problems while maintaining critical humility.", "children": [{"id": "d0af8fe9-d1bc-48a4-862c-23473b5a7d7a", "type": "subtopic", "title": "Program design and evaluation", "children": [{"id": "02991d0e-2b59-4ce5-a78c-cdc119dbde19", "type": "concept", "title": "Needs assessment"}, {"id": "587d2094-65b1-42e9-b946-a37898d1088b", "type": "concept", "title": "Logic models"}, {"id": "f8552819-d028-4ec0-90a5-5956c6de5b06", "type": "concept", "title": "Process evaluation"}, {"id": "3fa618f6-f878-4b8c-b73b-2be1a8f7c2d2", "type": "concept", "title": "Implementation ethnography"}], "description": "Students learn how ethnography can improve interventions by revealing assumptions, barriers, relationships, and local priorities."}, {"id": "daa1baf8-efea-4858-8334-9a3be7442eb0", "type": "subtopic", "title": "Policy and advocacy", "children": [{"id": "a3303b65-9b9a-49b4-9353-a245dfe963f7", "type": "concept", "title": "Policy memos"}, {"id": "f29aeb91-a369-431a-b6d3-07204d37bb3f", "type": "concept", "title": "Stakeholder analysis"}, {"id": "b78fd0e9-ad6f-409e-97f3-fbc275550565", "type": "concept", "title": "Health equity impact"}, {"id": "3b38c564-ff41-4e04-916b-e649f3269a43", "type": "concept", "title": "Public anthropology"}], "description": "This subtopic shows how anthropologists translate evidence into briefs, testimony, community partnerships, and institutional change."}, {"id": "fddaf2da-45cf-43b7-9dc9-401f026f6ae0", "type": "subtopic", "title": "Capstone case synthesis", "children": [{"id": "3821e021-25c3-47e8-b98e-7b3418907f55", "type": "concept", "title": "Comparative case analysis"}, {"id": "8d9035b2-dd18-4550-8f79-5a4ad55efb71", "type": "concept", "title": "Annotated bibliography"}, {"id": "1dc4b397-f230-49c6-9336-66bd47c746b6", "type": "concept", "title": "Ethnographic proposal"}, {"id": "a4793406-dba9-4791-bf65-79ad348eef22", "type": "concept", "title": "Presentation of findings"}], "description": "Students integrate theory, methods, ethics, and evidence in a final analysis of a health issue or care setting."}]}], "dbBacked": true}$medajson$::jsonb,
