}, {"id": "62a052be-6f79-4da6-a1fc-08333387f419", "type": "concept", "title": "Off-label use"}], "description": "Students explore how drugs move through research, regulation, marketing, prescription, adherence, and everyday life."}, {"id": "a50ccca2-385b-4118-a685-d733c8fe9006", "type": "subtopic", "title": "Genomics, biotechnology, and risk", "children": [{"id": "93e40b85-6872-4ee3-b2fa-f91653d8eb0c", "type": "concept", "title": "Genetic testing"}, {"id": "9d15da23-05ab-4c4d-b9a0-ea70e0d237b2", "type": "concept", "title": "Biobanks"}, {"id": "995103de-102c-42cc-97ba-e3cafdace9bc", "type": "concept", "title": "Precision medicine"}, {"id": "23c96762-7158-4aeb-bb86-d4452d528f58", "type": "concept", "title": "Epigenetics"}], "description": "This subtopic asks how molecular knowledge changes kinship, identity, prediction, and responsibility."}, {"id": "56f95b44-4338-4706-b4ee-540637cb92bb", "type": "subtopic", "title": "Digital health and datafication", "children": [{"id": "fd91c3b1-94cf-49cb-8fde-f6bd943ef5bc", "type": "concept", "title": "AI triage"}, {"id": "930f5c10-7242-42af-8b42-65c9e37b642f", "type": "concept", "title": "Data privacy"}, {"id": "ded0adb6-33d5-466c-b97a-b1ba8adbbb73", "type": "concept", "title": "Quantified self"}, {"id": "8d38c3ce-8aca-416e-b2b6-3c78b7f9c37b", "type": "concept", "title": "Platform medicine"}], "description": "Students analyze apps, algorithms, telehealth, wearables, and electronic records as cultural and political systems."}]}, {"id": "4eb893bb-7467-4b5d-aa79-5d3710e70bcb", "type": "topic", "title": "Migration, Labor, Environment, Climate, and Planetary Health", "description": "Students connect health to movement, work, borders, ecological change, and planetary systems.", "children": [{"id": "23439ee3-730e-4c5e-bc12-6a100abad091", "type": "subtopic", "title": "Migration and border health", "children": [{"id": "35c22367-876f-4f91-9974-16c094fbebd1", "type": "concept", "title": "Migrant farmwork"}, {"id": "06ee3858-209b-4507-9fb9-991b2d48ac01", "type": "concept", "title": "Refugee care"}, {"id": "beb816ac-da98-4703-8eb1-64e5efc04065", "type": "concept", "title": "Medical deportation"}, {"id": "2f075c00-b4c9-443e-a829-e98a9003f95b", "type": "concept", "title": "Transnational treatment seeking"}], "description": "This subtopic examines health across mobility, documentation status, asylum, detention, and transnational family life."}, {"id": "7d922bec-b5b2-4f1b-9d25-57a4a5650e43", "type": "subtopic", "title": "Labor, occupational health, and care work", "children": [{"id": "f04ef343-9dc6-441b-9c82-58cc05af45ba", "type": "concept", "title": "Precarious labor"}, {"id": "0b1b0d2a-bff3-482f-b741-6d976d713b39", "type": "concept", "title": "Essential work"}, {"id": "1bab7a2e-97d5-4f70-acb8-b3020f95a959", "type": "concept", "title": "Occupational injury"}, {"id": "99cbc318-a27f-45c1-b0b6-93b8e0c42974", "type": "concept", "title": "Care worker inequality"}], "description": "Students study how bodies absorb the costs of food systems, service work, extraction, and care economies."}, {"id": "d2325004-ef22-4e53-a795-fcc8cc4ec188", "type": "subtopic", "title": "Climate and planetary health", "children": [{"id": "e0a54075-e17e-466b-aad5-aa73f5e39b72", "type": "concept", "title": "Heat and housing"}, {"id": "9277072e-2d84-4414-bd78-d227aaabee24", "type": "concept", "title": "Air pollution"}, {"id": "65d71922-3179-4539-bbd4-028b982ec118", "type": "concept", "title": "Environmental racism"}, {"id": "472ac476-83fc-4dee-8622-a36756cf40e5", "type": "concept", "title": "Eco-anxiety"}], "description": "The goal is to link ecological disruption to health without losing sight of unequal responsibility and vulnerability."}]}, {"id": "54d5864e-4cd2-445e-a283-6db90d229acc", "type": "topic", "title": "Ethnographic Methods, Ethics, Translation, and Mixed Evidence", "description": "This section gives students the research craft needed to study medicine and health responsibly.", "children": [{"id": "913a05dd-fbce-49d8-8288-c09035dcf636", "type": "subtopic", "title": "Participant observation in health settings", "children": [{"id": "8b93ae23-d0e0-4f1b-b0a7-24bc26bc16bc", "type": "concept", "title": "Fieldsite access"}, {"id": "b65e7634-1b9a-4e6a-a449-49ecbad180df", "type": "concept", "title": "Observation protocols"}, {"id": "939159cb-718a-4229-8629-7c9b48efa309", "type": "concept", "title": "Fieldnotes"}, {"id": "03617351-3b3b-4243-91a3-1ab973623e3f", "type": "concept", "title": "Researcher positionality"}], "description": "Students learn how to observe clinics, communities, households, and institutions while respecting vulnerability and confidentiality."}, {"id": "e13bae2f-6fb1-4203-9ff7-5656260aecaf", "type": "subtopic", "title": "Interviews, narratives, and qualitative analysis", "children": [{"id": "99e7a97c-bfa1-4277-b0b2-1fc4aee39150", "type": "concept", "title": "Semi-structured interviews"}, {"id": "b6b92f37-fea6-4266-a8e7-39e7fc2a6af7", "type": "concept", "title": "Oral histories"}, {"id": "aff2196a-84dd-45eb-9133-d8254582ce1e", "type": "concept", "title": "Coding"}, {"id": "4a395ba5-835f-46d5-b58a-308b04512b29", "type": "concept", "title": "Thematic analysis"}], "description": "This subtopic introduces rigorous qualitative design for illness stories, stakeholder perspectives, and program contexts."}, {"id": "46eef933-a52a-4051-b625-84c8d8bcfa6a", "type": "subtopic", "title": "Ethics, consent, and collaboration", "children": [{"id": "07667793-a2de-48c8-81a5-67f42cd9313a", "type": "concept", "title": "IRB"}, {"id": "29963148-ee91-4817-bbdb-b4c420a857fc", "type": "concept", "title": "Informed consent"}, {"id": "648b8b76-843a-4b1b-b4b1-1b131461a0fe", "type": "concept", "title": "Participatory methods"}, {"id": "2347f06c-7fbf-4912-a1dd-2df852a29517", "type": "concept", "title": "Data stewardship"}], "description": "Students practice research ethics beyond paperwork, emphasizing power, reciprocity, consent, and community benefit."}]}, {"id": "b989d0b4-57b8-4b85-81e2-49f8a07b3b83", "ty