  ('2b5bdf04-4656-4f72-9a2c-f6e612346195', 'f4a5b6c7-8d9e-4a14-9b34-4c5d6e7f8a44', null, 'topic'::public.curated_course_node_type, 'Biomedicine as a Cultural System and Clinical World', 'This section treats biomedicine not as culture-free science but as a powerful institution with values, rituals, hierarchies, technologies, and forms of knowledge.', 1),
  ('91386f6a-4e24-4d2c-b813-999d1788f16b', 'f4a5b6c7-8d9e-4a14-9b34-4c5d6e7f8a44', '2b5bdf04-4656-4f72-9a2c-f6e612346195', 'subtopic'::public.curated_course_node_type, 'Medicalization and diagnosis', 'Students examine how human problems become medical categories and why diagnostic labels can both help and constrain.', 0),
