  ('e856a55e-23b0-4b39-b043-62af4fb9fa37', 'f4a5b6c7-8d9e-4a14-9b34-4c5d6e7f8a44', '2b5bdf04-4656-4f72-9a2c-f6e612346195', 'subtopic'::public.curated_course_node_type, 'Clinical training and professional identity', 'This subtopic reveals how clinicians learn to see, speak, document, and decide within institutional norms.', 1),
