  ('8537f795-b0b9-4fc3-8016-c31eda6502de', 'f4a5b6c7-8d9e-4a14-9b34-4c5d6e7f8a44', 'f00020b0-6647-4a6a-9831-274290f045aa', 'subtopic'::public.curated_course_node_type, 'Plural medical systems', 'The goal is to understand why people often combine biomedical, religious, herbal, community, and household care.', 0),
