  ('c8486310-89b3-42f6-ad39-c8998470fd81', 'f4a5b6c7-8d9e-4a14-9b34-4c5d6e7f8a44', null, 'topic'::public.curated_course_node_type, 'Biocultural Anthropology, Evolution, Nutrition, and Human Adaptation', 'Medical anthropology becomes strongest when students can connect biology and culture without collapsing one into the other.', 3),
