  ('b733ff48-ec26-4c71-8a20-ef1832604aa8', 'f4a5b6c7-8d9e-4a14-9b34-4c5d6e7f8a44', null, 'topic'::public.curated_course_node_type, 'Structural Violence, Social Determinants, Inequality, and Health Justice', 'Students learn to move beyond individual behavior explanations and analyze how institutions, histories, policies, and economies produce patterned suffering.', 4),
